using System;using UnityEngine;using OneWay.Battle3D;
public static class TestIdleShieldAngle {
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);}
 public static object Run(){var c=UnityEngine.Object.FindFirstObjectByType<NewPlayerAttackCombo>();var p=c.GetComponent<BattlePlayerController>();var m=p.GetComponent<NewPlayerLocomotion>();var shield=p.shield.transform;bool pe=p.enabled,input=c.readMouseInput;var pos=shield.localPosition;var scale=shield.localScale;p.enabled=false;c.readMouseInput=false;p.CancelInput();m.SetDefenseMode(false);m.SendMessage("LateUpdate");var original=shield.localRotation;
 try{m.SetDefenseMode(true);for(int i=0;i<100;i++)m.SendMessage("LateUpdate");var corrected=shield.localRotation;Check(Vector3.Distance(shield.localPosition,pos+m.idleShieldPositionOffset)<.001f,"Idle position offset missing");Check(Quaternion.Angle(corrected,original*Quaternion.Euler(m.idleShieldRotationOffset))<.05f,"Idle offset not applied");Check(Quaternion.Angle(corrected,original)>10,"Idle angle unchanged");m.StartParry();m.SendMessage("LateUpdate");Check(Quaternion.Angle(shield.localRotation,original)<.05f,"Parry attachment changed");c.Tick(1.2f);m.SendMessage("LateUpdate");Check(Quaternion.Angle(shield.localRotation,original)<.05f,"Held parry changed");m.ReleaseGuard();for(int i=0;i<100;i++)m.SendMessage("LateUpdate");Check(Quaternion.Angle(shield.localRotation,corrected)<.05f,"Idle return failed");m.StartRoll();m.SendMessage("LateUpdate");Check(Quaternion.Angle(shield.localRotation,original)<.05f,"Roll attachment changed");Check(shield.localPosition==pos&&shield.localScale==scale,"Attachment size/position changed");return new{passed=true,idleOffset=m.idleShieldRotationOffset.ToString(),parryUnchanged=true,rollUnchanged=true,positionAndScaleUnchanged=true};}
 finally{p.CancelInput();m.SetDefenseMode(false);m.SendMessage("LateUpdate");p.enabled=pe;c.readMouseInput=input;}}
}

